states.31990d408864:
[
 {
  "date": "2025-03-14",
  "source": "Bank statement",
  "entry": "Faster Payment £9,800.00 to 'W Hollis t/a Steel City Extensions', reference 'KITCHEN EXT DEPOSIT 40%'. Contract price £24,500.00; work due to start 7 April 2025."
 },
 {
  "date": "2025-04-07",
  "source": "Customer's account",
  "entry": "Mr Hollis did not start; texted that materials were delayed."
 },
 {
  "date": "2025-04-25",
  "source": "Customer's account",
  "entry": "'His phone went dead for a week. That's when I started to worry it might be a con.'"
 },
 {
  "date": "2025-04-26",
  "source": "Customer's account",
  "entry": "Found a post in a local Facebook group from another homeowner saying Wayne had taken her deposit and vanished."
 },
 {
  "date": "2025-05-02",
  "source": "Customer's account",
  "entry": "Mr Hollis resurfaced, apologised, said his mother had been in hospital, sent photos of timber and blocks 'in my yard' and gave a new start date of 2 June."
 },
 {
  "date": "2025-06-02",
  "source": "Customer's account",
  "entry": "Mr Hollis did not turn up; he stopped replying to messages on 5 June."
 },
 {
  "date": "2025-06-20",
  "source": "Ashbourne Bank claim note",
  "entry": "Mrs Janet Whitlock (58, Sheffield) reports the payment as a scam by phone, mentioning the dead phone, the Facebook post and the two missed start dates. Agent asks whether anything affects her ability to deal with the claim; she says 'I just want my money back'. Receiving bank contacted."
 },
 {
  "date": "2025-06-27",
  "source": "Receiving bank reply",
  "entry": "Long-standing business account opened in 2019; regular card spending at builders' merchants until March 2025; current balance £212."
 },
 {
  "date": "2025-07-03",
  "source": "Ashbourne decision",
  "entry": "Claim declined: 'Mr Hollis is an established trader with a history of completed jobs. His failure to carry out the work is a private civil dispute, which the reimbursement rules do not cover.'"
 },
 {
  "date": "2025-08-01",
  "source": "Ashbourne final response",
  "entry": "Decline maintained."
 },
 {
  "date": "2025-08-12",
  "source": "Financial Ombudsman Service",
  "entry": "Complaint referred."
 },
 {
  "date": "2025-08-28",
  "source": "South Yorkshire Police via Trading Standards",
  "entry": "Mr Hollis has been charged with fraud by false representation: between January and May 2025 he took deposits from 14 households and bought no materials for any of them after February 2025; the 'yard' photos were of another firm's premises."
 },
 {
  "date": "2025-09-15",
  "source": "Ashbourne reassessment",
  "entry": "Claim now accepted as an APP scam. Note: 'Customer suspected a scam on 25 April but reported on 20 June. The builder's reappearance on 2 May with an explanation and photos makes the delay understandable; consumer standard of caution not applied.'"
 },
 {
  "date": "2025-09-19",
  "source": "Ashbourne",
  "entry": "£9,700.00 credited (£9,800.00 less £100.00 excess)."
 },
 {
  "date": "2025-09-24",
  "source": "Ombudsman investigator call note",
  "entry": "Mrs Whitlock wants 8% interest from 3 July, £250 for distress and the £100 excess back. She explains she was widowed in January 2025 and is the sole carer for her adult son, who has cerebral palsy - 'that's why I didn't chase things sooner'."
 },
 {
  "date": "2025-10-06",
  "source": "Ashbourne offer",
  "entry": "8% simple interest on £9,700.00 from 3 July 2025 to 19 September 2025, plus £100 for distress and inconvenience. Excess maintained because 'no vulnerability was disclosed when the claim was made'."
 },
 {
  "date": "2025-10-14",
  "source": "Customer",
  "entry": "Accepts the interest and the £100, but still disputes the excess."
 },
 {
  "date": "2025-10-21",
  "source": "Ashbourne",
  "entry": "Having reviewed the circumstances shared by the investigator, records Mrs Whitlock as vulnerable at the time of the scam and agrees to refund the £100 excess."
 },
 {
  "date": "2025-10-27",
  "source": "Financial Ombudsman Service",
  "entry": "Mrs Whitlock accepts; case closed as resolved by agreement."
 }
]
